"""Explicit host adjudications after an independent agent audit, not automatic relabelling."""
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from physstyle.common import *
ds=read_jsonl('data/annotations/host_decisions.jsonl')
# window -> selected item, observed timing (same_introduction excludes a later equation+where sentence)
items=[('s^i','same_introduction'),('\\rho','same_introduction'),('a','same_introduction'),('\\mathcal{F}','same_introduction'),('g','after'),('\\varepsilon','after'),('a_{i}','after'),('', 'no_new_item'),('time','same_introduction'),('\\lambda_c','after'),('\\eta_*','unknown'),('V_{(p)}','after'),('\\tilde A','same_introduction'),('S_i','after'),('K_{ij}','after'),('\\beta_i','same_introduction'),('f','after'),('a_f','same_introduction'),('\\rho^{(i)}','same_introduction'),('\\alpha','after'),('a(t)','after'),('G_{1}','same_introduction'),('c','unknown'),('p','same_introduction'),('', 'no_new_item'),('', 'no_new_item'),('R_0','same_introduction'),('Q','after'),('', 'unknown'),('\\Lambda','after'),('g_{IJ}','after'),('R^N_M','same_introduction'),('r_f','same_introduction'),('\\mathcal{E}^c','after'),('\\dot','same_introduction'),('q_{0}','after'),('', 'unknown'),('N_e','after'),('', 'no_new_item'),('t_{M}','same_introduction'),('', 'no_new_item'),('A','after'),('\\Sigma','after'),('', 'no_new_item'),('Q','after'),('\\sigma','after'),('\\lambda','after'),('f(\\tau)','same_introduction'),('\\tilde{x}','same_introduction'),('D','after'),('q=u','same_introduction'),('\\tilde{\\varphi}','same_introduction'),('f','after'),('', 'unknown'),('J_i','same_introduction'),('Q','after'),('p(r)','after'),('\\eta','same_introduction'),('\\mu','after'),('s_0','same_introduction')]
label_for={'same_introduction':'yes','before':'yes','after':'no','unknown':'uncertain','no_new_item':'not_applicable'}
for d in ds:
 n=d['n'];symbol,timing=items[n];d['S04_item']={'symbol_or_concept':symbol or None,'definition_timing':timing,'scope':'one explicitly selected local item; not an exhaustive symbol audit or a global first-use assertion'}
 old=d['answers'][3];d['answers'][3]=[label_for[timing],old[1],f'Selected item {symbol or "unidentified/inherited"}: definition timing = {timing}. Strict local-use convention: a definition in a later equation-following sentence is after, not simultaneous. '+old[2]]
 if n==3:d['answers'][3][1]='fundamental domain'
 if n==18:d['answers'][3][1]='We will denote the moduli of the individual tori as';d['answers'][3][2]='Selected new rho^(i) and sigma^(i) in following context are introduced with their torus-moduli role in the same sentence; whole-window S04 scope, not just the target equation.'
 if n==59:d['answers'][3][2]='Selected s_0 and v_0 are explicitly introduced as wavefunction and potential at the origin before their first explicit local symbols; the generic coefficient series is not taken as an explicit first use of every coefficient.'
write_jsonl('data/annotations/host_decisions.jsonl',ds)
write_json('configs/semantic_protocol.json',{'version':'semantic-v1.1','frozen_at':now(),'change_reason':'Clarified after discovery-only agent audit, before writing strategy freeze and heldout fact-brief reading. No heldout semantic labels used.','scopes':{'S01':'target paragraph','S02':'explicit purpose BEFORE first target display, within supplied window','S03':'meaning/use/scope of target display AFTER it, within supplied window','S04':'explicitly selected newly introduced local item in full window; before or same introductory clause/defining identity yes; subsequent where sentence no; unestablished newness uncertain; no global claim','S05':'identified key transition in complete supplied window','S06':'identified principal claim in complete supplied window'},'sampling_warning':'formula-centered windows; not an unbiased paragraph sample; optional adjacent contexts may overlap','human_gold_standard':False})
